//! Host-owned CSR Vite URLs and immutable asset paths, generated by `build.rs`.

include!(concat!(env!("OUT_DIR"), "/csr_vite_data.rs"));

/// The Vite entry and WASM asset used by the static shell and public projector.
#[derive(Clone, Copy)]
pub(crate) struct BootAssets {
    pub(crate) entry_js: &'static str,
    pub(crate) wasm: &'static str,
}

pub(crate) fn boot_assets() -> Option<BootAssets> {
    boot_assets_from(ENTRY_JS_URL, WASM_URL)
}

fn boot_assets_from(
    entry_js: Option<&'static str>,
    wasm: Option<&'static str>,
) -> Option<BootAssets> {
    Some(BootAssets {
        entry_js: entry_js?,
        wasm: wasm?,
    })
}

pub(crate) fn is_vite_asset(logical_path: &str) -> bool {
    VITE_ASSET_PATHS.binary_search(&logical_path).is_ok()
}

pub(crate) fn early_wasm_fetch_script(assets: BootAssets) -> String {
    format!(
        "<script>\n      const __jaunderWasmUrl = \"{}\";\n      window.__jaunderWasmFetch = fetch(__jaunderWasmUrl);\n    </script>",
        assets.wasm
    )
}

pub(crate) fn module_entry_script(assets: BootAssets) -> String {
    format!(
        "<script type=\"module\" src=\"{}\"></script>",
        assets.entry_js
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn boot_assets_requires_both_vite_outputs() {
        assert!(boot_assets_from(Some("/assets/index.js"), Some("/assets/client.wasm")).is_some());
        assert!(boot_assets_from(None, Some("/assets/client.wasm")).is_none());
        assert!(boot_assets_from(Some("/assets/index.js"), None).is_none());
    }

    #[test]
    fn early_fetch_and_module_entry_use_the_vite_output_paths() {
        let assets = boot_assets_from(Some("/assets/index.js"), Some("/assets/client.wasm"))
            .expect("Vite outputs");
        assert!(
            early_wasm_fetch_script(assets)
                .contains("const __jaunderWasmUrl = \"/assets/client.wasm\";")
        );
        assert_eq!(
            module_entry_script(assets),
            "<script type=\"module\" src=\"/assets/index.js\"></script>"
        );
    }
}
